#include "genesis/learning/consolidation.hpp"
#include <cstdlib>
#include <iostream>
#include <stdexcept>
namespace {void require(bool v,const char*m){if(!v)throw std::runtime_error(m);}std::string d(char c){return std::string(64,c);}}
int main()try{using namespace genesis::learning;ConsolidationScheduler scheduler(5,4);require(scheduler.register_trace({"fact",TraceKind::declarative,.8,.3,.6,10,1,30,false}),"fact trace");require(scheduler.register_trace({"skill",TraceKind::procedural,.7,.2,.4,5,3,50,true}),"skill trace");require(scheduler.register_trace({"episode",TraceKind::episodic,.5,.8,.2,1,0,40,false}),"episode trace");require(!scheduler.register_trace({"fact",TraceKind::semantic,.1,.1,.1,0,0,1,false}),"duplicate trace accepted");require(scheduler.record_interference({"fact","episode",.9,d('a')}),"interference record");require(!scheduler.record_interference({"episode","fact",.5,d('b')}),"reverse duplicate interference accepted");require(!scheduler.record_interference({"missing","fact",.5,d('c')}),"missing trace interference accepted");auto first=scheduler.plan(100,70,3);require(first.reserved<=70&&first.items.size()==2&&!first.deferred.empty(),"bounded consolidation plan");require(first.items.front().trace_id=="episode","uncertainty and interference priority not applied deterministically");auto repeated=scheduler.plan(100,70,3);require(first.items[0].trace_id==repeated.items[0].trace_id&&first.items[1].trace_id==repeated.items[1].trace_id,"same inputs changed plan");require(scheduler.record_use("episode",101),"record trace use");require(!scheduler.record_use("episode",100),"time reversal accepted");require(scheduler.verify(),"learning scheduler invariants");std::cout<<"learning tests passed\n";return EXIT_SUCCESS;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return EXIT_FAILURE;}
